// Copyright (c) 2024 Yassine Bridi
// Config handling for serpl
use std::collections::HashMap;
use std::path::PathBuf;

use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum Action {
    Quit,
    Suspend,
    Refresh,
    LoopOverTabs,
    BackLoopOverTabs,
    ProcessReplace,
    ShowHelp,
}

impl std::str::FromStr for Action {
    type Err = String;
    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "Quit" => Ok(Action::Quit),
            "Suspend" => Ok(Action::Suspend),
            "Refresh" => Ok(Action::Refresh),
            "LoopOverTabs" => Ok(Action::LoopOverTabs),
            "BackLoopOverTabs" => Ok(Action::BackLoopOverTabs),
            "ProcessReplace" => Ok(Action::ProcessReplace),
            "ShowHelp" => Ok(Action::ShowHelp),
            "Help" => Ok(Action::ShowHelp),
            _ => Err(format!("Unknown Action variant: {}", s)),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct Key {
    pub code: KeyCode,
    pub modifiers: KeyModifiers,
}

impl Key {
    pub fn matches(&self, ev: &KeyEvent) -> bool {
        // Compare code and modifiers with special handling for Char case
        match (&self.code, &ev.code) {
            (KeyCode::Char(a), KeyCode::Char(b)) => {
                // If either has modifiers (Ctrl/Alt/Shift), compare lowercased
                // else compare exact (case-sensitive)
                let self_has_mod = self.modifiers != KeyModifiers::NONE;
                let ev_has_mod = ev.modifiers != KeyModifiers::NONE;
                // For unmodified (NONE), require exact char and exact modifiers (NONE)
                // For modified, lowercase and compare modifiers exact?
                // Actually for Shift+a ('A'+SHIFT) vs configured Shift+a ('a'+SHIFT):
                // configured 'a' lower, pressed 'A' upper, both SHIFT -> lowercase pressed to compare
                if !self_has_mod && !ev_has_mod {
                    a == b && self.modifiers == ev.modifiers
                } else {
                    // Modified: lowercase both and compare modifiers exact
                    // But need to handle Shift for letters? e.g., configured 'a'+SHIFT vs pressed 'A'+SHIFT
                    // lowercase both to 'a', compare modifiers SHIFT==SHIFT -> match
                    a.to_ascii_lowercase() == b.to_ascii_lowercase()
                        && self.modifiers == ev.modifiers
                }
            }
            _ => self.code == ev.code && self.modifiers == ev.modifiers,
        }
    }
}

pub fn default_keybindings() -> HashMap<Key, Action> {
    let mut m = HashMap::new();
    m.insert(parse_key("<Ctrl-d>").unwrap(), Action::Quit);
    m.insert(parse_key("<Ctrl-c>").unwrap(), Action::Quit);
    m.insert(parse_key("<Ctrl-z>").unwrap(), Action::Suspend);
    m.insert(parse_key("<Ctrl-r>").unwrap(), Action::Refresh);
    m.insert(parse_key("<Tab>").unwrap(), Action::LoopOverTabs);
    m.insert(parse_key("<Backtab>").unwrap(), Action::BackLoopOverTabs);
    m.insert(parse_key("<Ctrl-o>").unwrap(), Action::ProcessReplace);
    m.insert(parse_key("<Ctrl-b>").unwrap(), Action::ShowHelp);
    m
}

pub fn parse_key(s: &str) -> Result<Key, String> {
    let inner = if s.starts_with('<') && s.ends_with('>') && s.len() >= 2 {
        &s[1..s.len() - 1]
    } else {
        s
    };
    if inner.is_empty() {
        return Err(format!("Unable to parse {}", ""));
    }
    if inner.chars().count() == 1 {
        let c = inner.chars().next().unwrap();
        // Single char: if lowercase? Actually store lowercased? No, for unmodified single char,
        // original lowercases? "A" -> 'a'? Let's store lowercased to match observed ("A" matches 'a')
        // Wait "A" matches 'a' (lower), not 'A'. So store lowercased.
        // But what about single char that is already lowercase? Same.
        // For single char that is symbol like '!', lowercased same.
        // So always lowercase single char?
        // But then how to distinguish? All single chars lowercased.
        return Ok(Key {
            code: KeyCode::Char(c.to_ascii_lowercase()),
            modifiers: KeyModifiers::NONE,
        });
    }
    // Multi-char: lowercase and parse modifiers + key
    let lower = inner.to_lowercase();
    let mut rest = lower.as_str();
    let mut mods = KeyModifiers::NONE;
    loop {
        if let Some(r) = rest.strip_prefix("ctrl-") {
            mods.insert(KeyModifiers::CONTROL);
            rest = r;
        } else if let Some(r) = rest.strip_prefix("alt-") {
            mods.insert(KeyModifiers::ALT);
            rest = r;
        } else if let Some(r) = rest.strip_prefix("shift-") {
            mods.insert(KeyModifiers::SHIFT);
            rest = r;
        } else {
            break;
        }
        if rest.is_empty() {
            return Err(format!("Unable to parse {}", ""));
        }
    }
    // rest is key part (lowercased)
    if rest.is_empty() {
        return Err(format!("Unable to parse {}", ""));
    }
    if rest.chars().count() == 1 {
        let c = rest.chars().next().unwrap();
        // Single char with modifiers: store lowercased (already lower)
        // Special: if mods contains SHIFT and key is Tab? Actually Shift+Tab should be BackTab, not Tab+SHIFT?
        // Handle Shift+Tab -> BackTab+SHIFT? Or BackTab?
        // Pressed Shift+Tab is BackTab+SHIFT, so store BackTab+SHIFT for both "backtab" and "shift-tab"
        // For now, single char with mods: store Char(c) with mods
        return Ok(Key {
            code: KeyCode::Char(c),
            modifiers: mods,
        });
    }
    // Special names
    let code = match rest {
        "tab" => {
            if mods.contains(KeyModifiers::SHIFT) && mods == KeyModifiers::SHIFT {
                // Shift+Tab -> BackTab+SHIFT? Or BackTab?
                // Pressed is BackTab+SHIFT, so store BackTab+SHIFT
                return Ok(Key {
                    code: KeyCode::BackTab,
                    modifiers: KeyModifiers::SHIFT,
                });
            } else if mods == KeyModifiers::NONE {
                KeyCode::Tab
            } else {
                // Ctrl+Tab, Alt+Tab, etc.: Tab with mods?
                // Store Tab with mods (e.g., Ctrl+Tab -> Tab+CONTROL)
                return Ok(Key {
                    code: KeyCode::Tab,
                    modifiers: mods,
                });
            }
        }
        "backtab" => {
            // Backtab always BackTab+SHIFT? Pressed is BackTab+SHIFT, so store with SHIFT?
            // What if configured "<Backtab>" (no mods) vs pressed BackTab+SHIFT?
            // To match, store with SHIFT.
            // What about "<Ctrl-Backtab>"? Unlikely, but handle: BackTab with Ctrl+Shift?
            let mut m = mods;
            m.insert(KeyModifiers::SHIFT);
            return Ok(Key {
                code: KeyCode::BackTab,
                modifiers: m,
            });
        }
        "enter" => KeyCode::Enter,
        "esc" => KeyCode::Esc,
        "up" => KeyCode::Up,
        "down" => KeyCode::Down,
        "left" => KeyCode::Left,
        "right" => KeyCode::Right,
        "space" => KeyCode::Char(' '),
        "backspace" => KeyCode::Backspace,
        "delete" => KeyCode::Delete,
        "insert" => KeyCode::Insert,
        "home" => KeyCode::Home,
        "end" => KeyCode::End,
        "pageup" => KeyCode::PageUp,
        "pagedown" => KeyCode::PageDown,
        "f1" => KeyCode::F(1),
        "f2" => KeyCode::F(2),
        "f3" => KeyCode::F(3),
        "f4" => KeyCode::F(4),
        "f5" => KeyCode::F(5),
        "f6" => KeyCode::F(6),
        "f7" => KeyCode::F(7),
        "f8" => KeyCode::F(8),
        "f9" => KeyCode::F(9),
        "f10" => KeyCode::F(10),
        "f11" => KeyCode::F(11),
        "f12" => KeyCode::F(12),
        _ => {
            return Err(format!("Unable to parse {}", rest));
        }
    };
    Ok(Key {
        code,
        modifiers: mods,
    })
}
