pub fn load_config() -> Result<HashMap<Key, Action>, String> {
    let mut map = default_keybindings();
    let path = config_path();
    if !path.exists() { return Ok(map); }
    let content = std::fs::read_to_string(&path).map_err(|e| e.to_string())?;
    let cleaned = preprocess_json5(&content);
    let v: serde_json::Value = match serde_json::from_str(&cleaned) { Ok(v) => v, Err(e) => return Err(fmt_parse_err(e, &cleaned, &path)) };
    let obj = match v.as_object() { Some(o) => o, None => return Ok(map) };
    let kb_val = match obj.get("keybindings") { None => return Ok(map), Some(v) => v };
    let kb_obj = match kb_val.as_object() { Some(o) => o, None => return Err(format!("invalid type: {}, expected a map", json_type_str(kb_val))) };
    for (k, val) in kb_obj {
        let action_str = val_to_action_str(val, k, &path)?;
        let action: Action = match action_str.parse() { Ok(a) => a, Err(e) => return Err(e) };
        let key = parse_key(k).unwrap();
        map.insert(key, action);
    }
    Ok(map)
}
