fn compile_search_regex(pattern: &str, mode: SearchMode) -> Option<regex::Regex> {
    match mode {
        SearchMode::Simple => {
            let pat = format!("(?i){}", regex::escape(pattern));
            regex::Regex::new(&pat).ok()
        }
        SearchMode::MatchCase => {
            let pat = regex::escape(pattern);
            regex::Regex::new(&pat).ok()
        }
        SearchMode::MatchWholeWord => {
            let pat = format!(r"(?i)\b{}\b", regex::escape(pattern));
            regex::Regex::new(&pat).ok()
        }
        SearchMode::MatchCaseWholeWord => {
            let pat = format!(r"\b{}\b", regex::escape(pattern));
            regex::Regex::new(&pat).ok()
        }
        SearchMode::Regex => {
            regex::Regex::new(pattern).ok()
        }
    }
}
